const assert = require('node:assert/strict');
const path = require('node:path');
const fs = require('node:fs/promises');

const { createServer } = require('../../server/server.js');

const FIXTURES_DIR = path.join(__dirname, 'fixtures');
const WWW_DIR = path.join(FIXTURES_DIR, 'www');

async function startServer(t, options) {
  const started = await createServer(options).start({ port: 0 });
  t.after(async () => {
    await started.stop();
  });
  return started;
}

test('AC-004 GET / 返回入口文件内容与 text/html Content-Type', async (t) => {
  const { origin } = await startServer(t, { staticRoot: WWW_DIR });

  const res = await fetch(`${origin}/`);
  assert.equal(res.status, 200);
  assert.equal(res.headers.get('content-type'), 'text/html; charset=utf-8');

  const body = await res.text();
  const expected = await fs.readFile(path.join(WWW_DIR, 'index.html'), 'utf8');
  assert.equal(body, expected);
});

test('AC-004 静态资源按扩展名返回对应 Content-Type 与文件内容', async (t) => {
  const { origin } = await startServer(t, { staticRoot: WWW_DIR });

  const css = await fetch(`${origin}/styles.css`);
  assert.equal(css.status, 200);
  assert.equal(css.headers.get('content-type'), 'text/css; charset=utf-8');
  assert.equal(await css.text(), await fs.readFile(path.join(WWW_DIR, 'styles.css'), 'utf8'));

  const js = await fetch(`${origin}/app.js`);
  assert.equal(js.status, 200);
  assert.equal(js.headers.get('content-type'), 'text/javascript; charset=utf-8');
  assert.equal(await js.text(), await fs.readFile(path.join(WWW_DIR, 'app.js'), 'utf8'));
});

