test('AC-005 start({ port: 0 }) resolve { origin, port, stop } 且 stop() 完成后关闭连接', async () => {
  const started = await createServer().start({ port: 0 });

  assert.equal(typeof started.stop, 'function', '应返回 stop 函数');
