const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');

const { createServer } = require('../../server/server.js');

const FIXTURES_DIR = path.join(__dirname, 'fixtures');

async function startServer(t, options) {
  const started = await createServer(options).start({ port: 0 });
  t.after(async () => {
    await started.stop();
  });
  return started;
}

test('AC-001 默认 dataPath 经 createServer 启动后 GET /api/levels 返回 200 与恰好 5 个满足字段约束的关卡', async (t) => {
  const { origin } = await startServer(t);

  const res = await fetch(`${origin}/api/levels`);
  assert.equal(res.status, 200);
  assert.equal(res.headers.get('content-type'), 'application/json; charset=utf-8');

  const levels = await res.json();
  assert.ok(Array.isArray(levels), '响应体应为顶层数组');
  assert.equal(levels.length, 5, '关卡数量应恰好为 5');

  const ids = new Set();
  for (const level of levels) {
    assert.equal(typeof level, 'object');
    assert.ok(level !== null, '关卡应为对象');
    assert.ok(Number.isInteger(level.id) && level.id >= 1, `关卡 id 应为正整数，实际 ${level.id}`);
    assert.equal(typeof level.name, 'string', '关卡 name 应为字符串');
    assert.notEqual(level.name, '', '关卡 name 应非空');
    assert.ok(['easy', 'normal', 'hard'].includes(level.difficulty), `关卡 difficulty 非法：${level.difficulty}`);
    assert.equal(typeof level.description, 'string', '关卡 description 应为字符串');
    assert.ok(Number.isInteger(level.waves) && level.waves >= 1, `关卡 waves 应为正整数，实际 ${level.waves}`);
    ids.add(level.id);
  }
  assert.equal(ids.size, 5, '关卡 id 应唯一');
});

test('AC-002 数据缺失、JSON 解析失败与结构校验失败均返回 500 与 LEVEL_DATA_UNAVAILABLE 可读错误', async (t) => {
  const fixtures = [
    { name: '文件缺失', dataPath: path.join(FIXTURES_DIR, 'levels-missing.json') },
    { name: 'JSON 解析失败', dataPath: path.join(FIXTURES_DIR, 'levels-invalid-json.json') },
    { name: '结构校验失败', dataPath: path.join(FIXTURES_DIR, 'levels-invalid-structure.json') },
  ];

  for (const fixture of fixtures) {
    const { origin } = await startServer(t, { dataPath: fixture.dataPath });
    const res = await fetch(`${origin}/api/levels`);
    assert.equal(res.status, 500, `${fixture.name} 应返回 500`);
    assert.equal(res.headers.get('content-type'), 'application/json; charset=utf-8');

    const body = await res.json();
    assert.equal(typeof body.error, 'object', `${fixture.name} 响应应含 error 对象`);
    assert.equal(body.error.code, 'LEVEL_DATA_UNAVAILABLE', `${fixture.name} 错误码应为 LEVEL_DATA_UNAVAILABLE`);

    const message = body.error.message;
    assert.equal(typeof message, 'string', `${fixture.name} message 应为字符串`);
    assert.ok(message.length > 0, `${fixture.name} message 应为非空可读信息`);
    assert.ok(!message.includes(FIXTURES_DIR), 'message 不应泄漏夹具绝对路径');
    assert.ok(!message.includes(process.cwd()), 'message 不应泄漏工作目录绝对路径');
    assert.ok(!message.includes('node:'), 'message 不应包含运行时堆栈信息');
    assert.ok(!message.includes('\n'), 'message 不应是多行堆栈');
  }
});

test('AC-003 未知 API 路径返回 404 与 error.code/error.message JSON 错误体', async (t) => {
  const { origin } = await startServer(t);

  const res = await fetch(`${origin}/api/unknown`);
  assert.equal(res.status, 404);
  assert.equal(res.headers.get('content-type'), 'application/json; charset=utf-8');

  const body = await res.json();
  assert.equal(typeof body.error.code, 'string');
  assert.ok(body.error.code.length > 0);
  assert.equal(typeof body.error.message, 'string');
  assert.ok(body.error.message.length > 0);
});

test('AC-003 非允许方法请求 /api/levels 返回 405 与 error.code/error.message JSON 错误体', async (t) => {
  const { origin } = await startServer(t);

  for (const method of ['POST', 'PUT', 'DELETE']) {
    const res = await fetch(`${origin}/api/levels`, { method });
    assert.equal(res.status, 405, `${method} 应返回 405`);
    assert.equal(res.headers.get('content-type'), 'application/json; charset=utf-8');

    const body = await res.json();
    assert.equal(typeof body.error.code, 'string', `${method} 错误体应含 error.code`);
    assert.ok(body.error.code.length > 0);
    assert.equal(typeof body.error.message, 'string', `${method} 错误体应含 error.message`);
    assert.ok(body.error.message.length > 0);
  }
});
