55	async function handleRequest(req, res, config) {
56	  const method = req.method ?? 'GET';
57	
58	  let pathname;
59	  try {
60	    pathname = decodeURIComponent(new URL(req.url ?? '/', 'http://localhost').pathname);
61	  } catch {
62	    return sendText(res, 400, 'Bad Request');
