74	  if (pathname.startsWith('/api/')) {
75	    return sendJson(res, 404, {
76	      error: { code: 'NOT_FOUND', message: '未找到请求的 API 路径' },
77	    });
78	  }
79	  return serveStatic(res, pathname, config);
