{"content":"'use strict';

const http = require('node:http');
const path = require('node:path');
const fs = require('node:fs/promises');

const LEVEL_DATA_UNAVAILABLE = 'LEVEL_DATA_UNAVAILABLE';
const DIFFICULTIES = ['easy', 'normal', 'hard'];

const MIME_TYPES = {
  '.html': 'text/html; charset=utf-8',
  '.htm': 'text/html; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.mjs': 'text/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2',
};

function createServer(options = {}) {
  const staticRoot = options.staticRoot ?? 'web';
  const config = {
    dataPath: options.dataPath ?? 'data/levels.json',
    staticRoot,
    apiPath: options.apiPath ?? options.api_path ?? '/api/levels',
    pageEntryPath:
      options.pageEntryPath ?? options.page_entry_path ?? path.join(staticRoot, 'index.html'),
    defaultPort: options.defaultPort ?? options.default_port ?? 3000,
    portEnv: options.portEnv ?? options.port_env ?? 'PORT',
  };

  const httpServer = http.createServer((req, res) => {
    handleRequest(req, res, config).catch(() => {
      if (!res.headersSent) {
        sendJson(res, 500, { error: { code: 'INTERNAL_ERROR', message: '服务器内部错误' } });
      } else {
        res.destroy();
      }
    });
  });

  return {
    start: (startOptions = {}) => startServer(httpServer, config, startOptions),
  };
}

async function handleRequest(req, res, config) {
  const method = req.method ?? 'GET';

  let pathname;
  try {
    pathname = decodeURIComponent(new URL(req.url ?? '/', 'http://localhost').pathname);
  } catch {
    return sendText(res, 400, 'Bad Request');
  }

  if (method !== 'GET' && method !== 'HEAD') {
    return sendJson(res, 405, {
      error: { code: 'METHOD_NOT_ALLOWED', message: '该路径仅支持 GET 请求' },
    });
  }

  if (pathname === config.apiPath) {
    return serveLevels(res, config);
  }
  if (pathname.startsWith('/api/')) {
    return sendJson(res, 404, {
      error: { code: 'NOT_FOUND', message: '未找到请求的 API 路径' },
    });
  }
  return serveStatic(res, pathname, config);
}

async function serveLevels(res, config) {
  try {
    const levels = await loadLevels(config.dataPath);
    sendJson(res, 200, levels);
  } catch (error) {
    sendJson(res, 500, {
      error: { code: LEVEL_DATA_UNAVAILABLE, message: error.message },
    });
  }
}

async function loadLevels(dataPath) {
  let raw;
  try {
    raw = await fs.readFile(dataPath, 'utf8');
  } catch {
    throw new Error('关卡数据文件缺失或不可读');
  }

  let data;
  try {
    data = JSON.parse(raw);
  } catch {
    throw new Error('关卡数据 JSON 解析失败');
  }

  return validateLevels(data);
}

function validateLevels(data) {
  if (!Array.isArray(data)) {
    throw new Error('关卡数据必须是顶层数组');
  }

  const seenIds = new Set();
  data.forEach((level, index) => {
    const label = `第 ${index + 1} 关`;
    if (typeof level !== 'object' || level === null || Array.isArray(level)) {
      throw new Error(`${label} 必须是对象`);
    }
    if (!Number.isInteger(level.id) || level.id < 1) {
      throw new Error(`${label} 的 id 必须是正整数`);
    }
    if (typeof level.name !== 'string' || level.name.length === 0) {
      throw new Error(`${label} 缺少非空字符串字段 name`);
    }
    if (!DIFFICULTIES.includes(level.difficulty)) {
      throw new Error(`${label} 的 difficulty 必须是 easy、normal 或 hard`);
    }
    if (typeof level.description !== 'string') {
      throw new Error(`${label} 的 description 必须是字符串`);
    }
    if (!Number.isInteger(level.waves) || level.waves < 1) {
      throw new Error(`${label} 的 waves 必须是正整数`);
    }
    if (seenIds.has(level.id)) {
      throw new Error(`关卡 id ${level.id} 重复`);
    }
    seenIds.add(level.id);
  });

  return data;
}

async function serveStatic(res, pathname, config) {
  const rootDir = path.resolve(config.staticRoot);
  const requested = pathname === '/'
    ? config.pageEntryPath
    : path.join(config.staticRoot, pathname);
  const resolvedPath = path.resolve(requested);

  if (resolvedPath !== rootDir && !resolvedPath.startsWith(rootDir + path.sep)) {
    return sendText(res, 403, 'Forbidden');
  }

  let content;
  try {
    content = await fs.readFile(resolvedPath);
  } catch {
    return sendText(res, 404, 'Not Found');
  }

  const contentType = MIME_TYPES[path.extname(resolvedPath).toLowerCase()] ?? 'application/octet-stream';
  res.writeHead(200, { 'Content-Type': contentType });
  res.end(content);
}

function sendJson(res, statusCode, payload) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(payload));
}

function sendText(res, statusCode, message) {
  res.writeHead(statusCode, { 'Content-Type': 'text/plain; charset=utf-8' });
  res.end(message);
}

function startServer(httpServer, config, startOptions) {
  const envPort = Number.parseInt(process.env[config.portEnv] ?? '', 10);
  const port = startOptions.port ?? (Number.isNaN(envPort) ? undefined : envPort) ?? config.defaultPort;

  return new Promise((resolve, reject) => {
    const onError = (error) => {
      httpServer.off('error', onError);
      reject(error);
    };
    httpServer.once('error', onError);

    httpServer.listen(port, '127.0.0.1', () => {
      httpServer.off('error', onError);
      const actualPort = httpServer.address().port;
      resolve({
        origin: `http://127.0.0.1:${actualPort}`,
        port: actualPort,
        stop: () => stopServer(httpServer),
      });
    });
  });
}

function stopServer(httpServer) {
  return new Promise((resolve, reject) => {
    httpServer.close((error) => {
      if (error && error.code !== 'ERR_SERVER_NOT_RUNNING') {
        reject(error);
        return;
      }
      resolve();
    });
    httpServer.closeAllConnections();
  });
}

module.exports = { createServer };
