146	async function serveStatic(res, pathname, config) {
147	  const rootDir = path.resolve(config.staticRoot);
148	  const requested = pathname === '/'
149	    ? config.pageEntryPath
150	    : path.join(config.staticRoot, pathname);
151	  const resolvedPath = path.resolve(requested);
152	
153	  if (resolvedPath !== rootDir && !resolvedPath.startsWith(rootDir + path.sep)) {
154	    return sendText(res, 403, 'Forbidden');
155	  }
156	
157	  let content;
158	  try {
159	    content = await fs.readFile(resolvedPath);
160	  } catch {
161	    return sendText(res, 404, 'Not Found');
162	  }
163	
164	  const contentType = MIME_TYPES[path.extname(resolvedPath).toLowerCase()] ?? 'application/octet-stream';
165	  res.writeHead(200, { 'Content-Type': contentType });
166	  res.end(content);
167	}
