146	async function serveStatic(res, pathname, config) {
147	  const rootDir = path.resolve(config.staticRoot);
148	  const requested = pathname === '/'
149	    ? config.pageEntryPath
150	    : path.join(config.staticRoot, pathname);
151	  const resolvedPath = path.resolve(requested);
152	
153	  if (resolvedPath !== rootDir && !resolvedPath.startsWith(rootDir + path.sep)) {
154	    return sendText(res, 403, 'Forbidden');
155	  }
156	
157	  let content;
158	  try {
159	    content = await fs.readFile(resolvedPath);
160	  } catch {
161	    return sendText(res, 404, 'Not Found');
162	  }
163	
164	  const contentType = MIME_TYPES[path.extname(resolvedPath).toLowerCase()] ?? 'application/octet-stream';
165	  res.writeHead(200, { 'Content-Type': contentType });
166	  res.end(content);
167	}
168	
169	function sendJson(res, statusCode, payload) {
170	  res.writeHead(statusCode, { 'Content-Type': 'application/json; charset=utf-8' });
171	  res.end(JSON.stringify(payload));
172	}
173	
174	function sendText(res, statusCode, message) {
175	  res.writeHead(statusCode, { 'Content-Type': 'text/plain; charset=utf-8' });
176	  res.end(message);
177	}
178	
179	function startServer(httpServer, config, startOptions) {
180	  const envPort = Number.parseInt(process.env[config.portEnv] ?? '', 10);
181	  const port = startOptions.port ?? (Number.isNaN(envPort) ? undefined : envPort) ?? config.defaultPort;
182	
183	  return new Promise((resolve, reject) => {
184	    const onError = (error) => {
185	      httpServer.off('error', onError);
186	      reject(error);
187	    };
188	    httpServer.once('error', onError);
189	
190	    httpServer.listen(port, '127.0.0.1', () => {
191	      httpServer.off('error', onError);
192	      const actualPort = httpServer.address().port;
193	      resolve({
194	        origin: `http://127.0.0.1:${actualPort}`,
195	        port: actualPort,
196	        stop: () => stopServer(httpServer),
197	      });
198	    });
199	  });
200	}
201	
202	function stopServer(httpServer) {
203	  return new Promise((resolve, reject) => {
204	    httpServer.close((error) => {
205	      if (error && error.code !== 'ERR_SERVER_NOT_RUNNING') {
206	        reject(error);
207	        return;
208	      }
209	      resolve();
210	    });
211	    httpServer.closeAllConnections();
212	  });
213	}
214	
215	module.exports = { createServer };

