166	    ? config.pageEntryPath
167	    : path.join(config.staticRoot, pathname);
168	  const resolvedPath = path.resolve(requested);
169	
170	  if (resolvedPath !== rootDir && !resolvedPath.startsWith(rootDir + path.sep)) {
171	    return sendText(res, 403, 'Forbidden');
172	  }
173	
174	  let content;
175	  try {
176	    content = await fs.readFile(resolvedPath);
177	  } catch {
178	    return sendText(res, 404, 'Not Found');
179	  }
