const test = require('node:test');
const assert = require('node:assert/strict');

const { createDocument, jsonResponse, textOf, VALID_LEVELS } = require('./helpers.js');

let initLevelSelect;
try {
  ({ initLevelSelect } = require('../../web/level-select.js'));
} catch (error) {
  if (error.code !== 'MODULE_NOT_FOUND') {
    throw error;
  }
  initLevelSelect = undefined;
}

function assertFramePreserved(doc) {
  assert.ok(doc.getElementById('loading') !== null, '页面框架应保留：#loading 仍在文档中');
  assert.ok(doc.getElementById('level-list') !== null, '页面框架应保留：#level-list 仍在文档中');
  assert.ok(doc.getElementById('error-message') !== null, '页面框架应保留：#error-message 仍在文档中');
}

test('AC-007 web/level-select.js 导出 initLevelSelect 函数', () => {
  assert.equal(typeof initLevelSelect, 'function', 'web/level-select.js 应导出 initLevelSelect 函数');
});

test('AC-007 请求期间先呈现加载态：loading 可见、错误提示隐藏、列表为空，并以相对路径 /api/levels 请求', () => {
  assert.equal(typeof initLevelSelect, 'function', 'web/level-select.js 应导出 initLevelSelect 函数');

  const doc = createDocument();
  const requestedUrls = [];
  const neverSettles = new Promise(() => {});

  initLevelSelect({
    document: doc,
    fetchImpl(url) {
      requestedUrls.push(url);
      return neverSettles;
    },
  });

  assert.deepEqual(requestedUrls, ['/api/levels'], '应以相对路径 /api/levels 请求关卡数据');
  assert.equal(doc.getElementById('loading').hasAttribute('hidden'), false, '加载中 loading 应可见');
  assert.equal(doc.getElementById('error-message').hasAttribute('hidden'), true, '加载中错误提示应隐藏');
  assert.equal(doc.getElementById('level-list').children.length, 0, '加载中关卡列表应为空');
});

test('AC-007 合法 5 项数组渲染 5 个含名称与难度的条目，unlocked=false 条目锁定不可选', async () => {
  assert.equal(typeof initLevelSelect, 'function', 'web/level-select.js 应导出 initLevelSelect 函数');

  const doc = createDocument();
  await initLevelSelect({
    document: doc,
    fetchImpl: async () => jsonResponse(VALID_LEVELS),
  });

  const list = doc.getElementById('level-list');
  assert.equal(list.children.length, 5, '应渲染 5 个关卡条目');

  list.children.forEach((item, index) => {
    const level = VALID_LEVELS[index];
    const itemText = textOf(item);
    assert.ok(itemText.includes(level.name), `第 ${index + 1} 项应包含关卡名称「${level.name}」`);
    assert.ok(itemText.includes(level.difficulty), `第 ${index + 1} 项应包含难度「${level.difficulty}」`);

    if (level.unlocked) {
      assert.ok(!/locked/.test(item.className), `已解锁条目 ${level.id} 不应携带锁定样式`);
      assert.ok((item.listeners.click ?? []).length > 0, `已解锁条目 ${level.id} 应可点选`);
      assert.notEqual(item.getAttribute('aria-disabled'), 'true', `已解锁条目 ${level.id} 不应标记不可选`);
    } else {
      assert.ok(/locked/.test(item.className), `未解锁条目 ${level.id} 应携带锁定样式`);
      assert.equal(item.getAttribute('aria-disabled'), 'true', `未解锁条目 ${level.id} 应标记不可选`);
      assert.equal(item.listeners.click, undefined, `未解锁条目 ${level.id} 不应注册点选处理器`);
    }
  });

  assert.equal(doc.getElementById('loading').hasAttribute('hidden'), true, '渲染完成后 loading 应隐藏');
  assert.equal(doc.getElementById('error-message').hasAttribute('hidden'), true, '成功时错误提示应隐藏');
  assert.equal(doc.getElementById('error-message').textContent, '', '成功时错误提示应为空');
  assertFramePreserved(doc);
});

test('AC-008 fetch 抛出异常时显示可读错误提示且页面框架保留', async () => {
  assert.equal(typeof initLevelSelect, 'function', 'web/level-select.js 应导出 initLevelSelect 函数');

  const doc = createDocument();
  await initLevelSelect({
    document: doc,
    fetchImpl: async () => {
      throw new Error('网络中断');
    },
  });

  const errorBox = doc.getElementById('error-message');
  assert.equal(errorBox.hasAttribute('hidden'), false, '错误提示应可见');
  assert.ok(errorBox.textContent.trim().length > 0, '错误提示应为非空可读文本');
  assert.equal(doc.getElementById('loading').hasAttribute('hidden'), true, '失败后 loading 应隐藏');
  assert.equal(doc.getElementById('level-list').children.length, 0, '失败时不应渲染关卡条目');
  assertFramePreserved(doc);
});

test('AC-008 非 2xx JSON 错误体显示含状态码与服务器错误信息的可读提示', async () => {
  assert.equal(typeof initLevelSelect, 'function', 'web/level-select.js 应导出 initLevelSelect 函数');

  const doc = createDocument();
  const payload = { error: { code: 'LEVEL_DATA_UNAVAILABLE', message: '关卡数据文件缺失或不可读' } };

  await initLevelSelect({
    document: doc,
    fetchImpl: async () => jsonResponse(payload, 500),
  });

  const errorBox = doc.getElementById('error-message');
  assert.equal(errorBox.hasAttribute('hidden'), false, '错误提示应可见');
  assert.ok(errorBox.textContent.includes('500'), '错误提示应包含 HTTP 状态码');
  assert.ok(
    errorBox.textContent.includes(payload.error.message),
    '错误提示应包含服务器返回的可读错误信息'
  );
  assert.equal(doc.getElementById('level-list').children.length, 0, '失败时不应渲染关卡条目');
  assertFramePreserved(doc);
});

test('AC-008 非 2xx 且响应体不可解析为 JSON 时仍显示可读错误提示', async () => {
  assert.equal(typeof initLevelSelect, 'function', 'web/level-select.js 应导出 initLevelSelect 函数');

  const doc = createDocument();
  await initLevelSelect({
    document: doc,
    fetchImpl: async () => jsonResponse(new SyntaxError('Unexpected token'), 503),
  });

  const errorBox = doc.getElementById('error-message');
  assert.equal(errorBox.hasAttribute('hidden'), false, '错误提示应可见');
  assert.ok(errorBox.textContent.trim().length > 0, '错误提示应为非空可读文本');
  assert.equal(doc.getElementById('level-list').children.length, 0, '失败时不应渲染关卡条目');
  assertFramePreserved(doc);
});

test('AC-008 2xx 但响应体非法 JSON 时显示可读错误提示且页面框架保留', async () => {
  assert.equal(typeof initLevelSelect, 'function', 'web/level-select.js 应导出 initLevelSelect 函数');

  const doc = createDocument();
  await initLevelSelect({
    document: doc,
    fetchImpl: async () => jsonResponse(new SyntaxError('Unexpected token'), 200),
  });

  const errorBox = doc.getElementById('error-message');
  assert.equal(errorBox.hasAttribute('hidden'), false, '错误提示应可见');
  assert.ok(errorBox.textContent.trim().length > 0, '错误提示应为非空可读文本');
  assert.equal(doc.getElementById('level-list').children.length, 0, '失败时不应渲染关卡条目');
  assertFramePreserved(doc);
});

test('AC-008 字段不满足 CT-002 约束的响应进入错误分支且页面框架保留', async () => {
  assert.equal(typeof initLevelSelect, 'function', 'web/level-select.js 应导出 initLevelSelect 函数');

  const withOverrides = (index, overrides) => ({ ...VALID_LEVELS[index], ...overrides });
  const cases = [
    { name: '顶层数据不是数组', payload: { levels: VALID_LEVELS } },
    { name: '关卡元素是字符串', payload: ['level-1'] },
    { name: 'id 为空字符串', payload: [withOverrides(0, { id: '' })] },
    { name: 'id 重复', payload: [VALID_LEVELS[0], { ...VALID_LEVELS[1], id: VALID_LEVELS[0].id }] },
    { name: 'name 为空字符串', payload: [withOverrides(0, { name: '' })] },
    { name: 'difficulty 非法', payload: [withOverrides(0, { difficulty: '地狱' })] },
    { name: 'unlocked 非布尔', payload: [withOverrides(0, { unlocked: 'true' })] },
  ];

  for (const testCase of cases) {
    const doc = createDocument();
    await initLevelSelect({
      document: doc,
      fetchImpl: async () => jsonResponse(testCase.payload),
    });

    const errorBox = doc.getElementById('error-message');
    assert.equal(
      errorBox.hasAttribute('hidden'),
      false,
      `[${testCase.name}] 错误提示应可见`
    );
    assert.ok(errorBox.textContent.trim().length > 0, `[${testCase.name}] 错误提示应为非空可读文本`);
    assert.equal(doc.getElementById('loading').hasAttribute('hidden'), true, `[${testCase.name}] loading 应隐藏`);
    assert.equal(doc.getElementById('level-list').children.length, 0, `[${testCase.name}] 不应渲染关卡条目`);
    assertFramePreserved(doc);
  }
});
