7	function createElement(tagName) {
8	  const element = {
9	    tagName: String(tagName).toUpperCase(),
10	    className: '',
11	    children: [],
12	    attributes: {},
13	    listeners: {},
14	  };
15	
16	  let text = '';
17	  Object.defineProperty(element, 'textContent', {
18	    get() {
19	      return text;
20	    },
21	    set(value) {
22	      text = String(value);
23	      element.children = [];
24	    },
25	  });
26	
27	  element.appendChild = (child) => {
28	    element.children.push(child);
29	    return child;
30	  };
31	  element.setAttribute = (name, value) => {
32	    element.attributes[name] = String(value);
33	  };
34	  element.getAttribute = (name) =>
35	    Object.prototype.hasOwnProperty.call(element.attributes, name) ? element.attributes[name] : null;
36	  element.hasAttribute = (name) => Object.prototype.hasOwnProperty.call(element.attributes, name);
37	  element.removeAttribute = (name) => {
38	    delete element.attributes[name];
39	  };
40	  element.addEventListener = (type, handler) => {
41	    if (!Object.prototype.hasOwnProperty.call(element.listeners, type)) {
42	      element.listeners[type] = [];
43	    }
44	    element.listeners[type].push(handler);
45	  };
46	
47	  return element;
48	}
