111	function validateLevels(data) {
112	  if (!Array.isArray(data)) {
113	    throw new Error('关卡数据必须是顶层数组');
114	  }
115	
116	  const seenIds = new Set();
117	  data.forEach((level, index) => {
118	    const label = `第 ${index + 1} 关`;
119	    if (typeof level !== 'object' || level === null || Array.isArray(level)) {
120	      throw new Error(`${label} 必须是对象`);
121	    }
122	    if (!Number.isInteger(level.id) || level.id < 1) {
123	      throw new Error(`${label} 的 id 必须是正整数`);
124	    }
125	    if (typeof level.name !== 'string' || level.name.length === 0) {
126	      throw new Error(`${label} 缺少非空字符串字段 name`);
127	    }
128	    if (!DIFFICULTIES.includes(level.difficulty)) {
129	      throw new Error(`${label} 的 difficulty 必须是 easy、normal 或 hard`);
130	    }
131	    if (typeof level.description !== 'string') {
132	      throw new Error(`${label} 的 description 必须是字符串`);
133	    }
134	    if (!Number.isInteger(level.waves) || level.waves < 1) {
135	      throw new Error(`${label} 的 waves 必须是正整数`);
136	    }
137	    if (seenIds.has(level.id)) {
138	      throw new Error(`关卡 id ${level.id} 重复`);
139	    }
140	    seenIds.add(level.id);
141	  });
142	
143	  return data;
144	}
