179	function startServer(httpServer, config, startOptions) {
180	  const envPort = Number.parseInt(process.env[config.portEnv] ?? '', 10);
181	  const port = startOptions.port ?? (Number.isNaN(envPort) ? undefined : envPort) ?? config.defaultPort;
182	
183	  return new Promise((resolve, reject) => {
184	    const onError = (error) => {
185	      httpServer.off('error', onError);
186	      reject(error);
187	    };
188	    httpServer.once('error', onError);
189	
190	    httpServer.listen(port, '127.0.0.1', () => {
191	      httpServer.off('error', onError);
192	      const actualPort = httpServer.address().port;
193	      resolve({
194	        origin: `http://127.0.0.1:${actualPort}`,
195	        port: actualPort,
196	        stop: () => stopServer(httpServer),
197	      });
198	    });
199	  });
200	}
201	
202	function stopServer(httpServer) {
203	  return new Promise((resolve, reject) => {
204	    httpServer.close((error) => {
205	      if (error && error.code !== 'ERR_SERVER_NOT_RUNNING') {
206	        reject(error);
207	        return;
208	      }
209	      resolve();
210	    });
211	    httpServer.closeAllConnections();
212	  });
213	}
