// 最小 DOM / fetch 替身，仅覆盖 initLevelSelect 依赖的接口子集。

const CONTAINER_IDS = ['loading', 'level-list', 'error-message'];

function createElement(tagName) {
  const element = {
    tagName: String(tagName).toUpperCase(),
    className: '',
    children: [],
    attributes: {},
    listeners: {},
  };

  let text = '';
  Object.defineProperty(element, 'textContent', {
    get() {
      return text;
    },
    set(value) {
      text = String(value);
      element.children = [];
    },
  });

  element.appendChild = (child) => {
    element.children.push(child);
    return child;
  };
  element.setAttribute = (name, value) => {
    element.attributes[name] = String(value);
  };
  element.getAttribute = (name) =>
    Object.prototype.hasOwnProperty.call(element.attributes, name) ? element.attributes[name] : null;
  element.hasAttribute = (name) => Object.prototype.hasOwnProperty.call(element.attributes, name);
  element.removeAttribute = (name) => {
    delete element.attributes[name];
  };
  element.addEventListener = (type, handler) => {
    if (!Object.prototype.hasOwnProperty.call(element.listeners, type)) {
      element.listeners[type] = [];
    }
    element.listeners[type].push(handler);
  };

  return element;
}

function createDocument() {
  const elements = new Map(CONTAINER_IDS.map((id) => [id, createElement('div')]));
  return {
    elements,
    getElementById(id) {
      return elements.get(id) ?? null;
    },
    createElement,
  };
}

function textOf(element) {
  const own = typeof element.textContent === 'string' ? element.textContent : '';
  return own + element.children.map(textOf).join('');
}

function jsonResponse(payload, status = 200) {
  return {
    status,
    ok: status >= 200 && status < 300,
    async json() {
      if (payload instanceof Error) {
        throw payload;
      }
      return payload;
    },
  };
}

// 仅包含 CT-002 约束的字段，验证前端不依赖 description/waves 等附加字段。
const VALID_LEVELS = [
  { id: 'level-1', name: '木叶村外围', difficulty: '简单', unlocked: true },
  { id: 'level-2', name: '波之国大桥', difficulty: '简单', unlocked: true },
  { id: 'level-3', name: '中忍考试之森', difficulty: '普通', unlocked: false },
  { id: 'level-4', name: '晓之突袭', difficulty: '困难', unlocked: false },
  { id: 'level-5', name: '终结谷之战', difficulty: '困难', unlocked: false },
];

module.exports = {
  CONTAINER_IDS,
  createElement,
  createDocument,
  textOf,
  jsonResponse,
  VALID_LEVELS,
};
