7	const LEVEL_DATA_UNAVAILABLE = 'LEVEL_DATA_UNAVAILABLE';
8	const DIFFICULTIES = ['简单', '普通', '困难'];
9	
10	const MIME_TYPES = {
11	  '.html': 'text/html; charset=utf-8',
12	  '.htm': 'text/html; charset=utf-8',
13	  '.css': 'text/css; charset=utf-8',
14	  '.js': 'text/javascript; charset=utf-8',
15	  '.mjs': 'text/javascript; charset=utf-8',
16	  '.json': 'application/json; charset=utf-8',
17	  '.txt': 'text/plain; charset=utf-8',
18	  '.svg': 'image/svg+xml',
19	  '.png': 'image/png',
20	  '.jpg': 'image/jpeg',
21	  '.jpeg': 'image/jpeg',
22	  '.gif': 'image/gif',
23	  '.ico': 'image/x-icon',
24	  '.woff': 'font/woff',
25	  '.woff2': 'font/woff2',
26	};
