28	function createServer(options = {}) {
29	  const staticRoot = options.staticRoot ?? 'web';
30	  const config = {
31	    dataPath: options.dataPath ?? 'data/levels.json',
32	    staticRoot,
33	    apiPath: options.apiPath ?? options.api_path ?? '/api/levels',
34	    pageEntryPath:
35	      options.pageEntryPath ?? options.page_entry_path ?? path.join(staticRoot, 'index.html'),
36	    defaultPort: options.defaultPort ?? options.default_port ?? 3000,
37	    portEnv: options.portEnv ?? options.port_env ?? 'PORT',
38	  };
39	
40	  const httpServer = http.createServer((req, res) => {
41	    handleRequest(req, res, config).catch(() => {
42	      if (!res.headersSent) {
43	        sendJson(res, 500, { error: { code: 'INTERNAL_ERROR', message: '服务器内部错误' } });
44	      } else {
45	        res.destroy();
46	      }
47	    });
48	  });
