96	async function serveLevels(res, config) {
97	  try {
98	    const levels = await loadLevels(config.dataPath);
99	    sendJson(res, 200, levels);
100	  } catch (error) {
101	    sendJson(res, 500, {
102	      error: { code: LEVEL_DATA_UNAVAILABLE, message: error.message },
103	    });
104	  }
105	}
106	
107	async function loadLevels(dataPath) {
108	  let raw;
109	  try {
110	    raw = await fs.readFile(dataPath, 'utf8');
111	  } catch {
112	    throw new Error('关卡数据文件缺失或不可读');
113	  }
114	
115	  let data;
116	  try {
117	    data = JSON.parse(raw);
118	  } catch {
119	    throw new Error('关卡数据 JSON 解析失败');
120	  }
121	
122	  return validateLevels(data);
123	}
124	
125	function validateLevels(data) {
126	  if (!Array.isArray(data)) {
127	    throw new Error('关卡数据必须是顶层数组');
128	  }
129	
130	  const seenIds = new Set();
131	  data.forEach((level, index) => {
132	    const label = `第 ${index + 1} 关`;
133	    if (typeof level !== 'object' || level === null || Array.isArray(level)) {
134	      throw new Error(`${label} 必须是对象`);
135	    }
136	    if (typeof level.id !== 'string' || level.id.length === 0) {
137	      throw new Error(`${label} 的 id 必须是非空字符串`);
138	    }
139	    if (typeof level.name !== 'string' || level.name.length === 0) {
140	      throw new Error(`${label} 缺少非空字符串字段 name`);
141	    }
142	    if (!DIFFICULTIES.includes(level.difficulty)) {
143	      throw new Error(`${label} 的 difficulty 必须是 简单、普通 或 困难`);
144	    }
145	    if (typeof level.unlocked !== 'boolean') {
146	      throw new Error(`${label} 的 unlocked 必须是布尔值`);
147	    }
148	    if (typeof level.description !== 'string') {
149	      throw new Error(`${label} 的 description 必须是字符串`);
150	    }
151	    if (!Number.isInteger(level.waves) || level.waves < 1) {
152	      throw new Error(`${label} 的 waves 必须是正整数`);
153	    }
154	    if (seenIds.has(level.id)) {
155	      throw new Error(`关卡 id ${level.id} 重复`);
156	    }
157	    seenIds.add(level.id);
158	  });
159	
160	  return data;
161	}
162	
163	async function serveStatic(res, pathname, config) {
164	  const rootDir = path.resolve(config.staticRoot);
165	  const requested = pathname === '/'
166	    ? config.pageEntryPath
167	    : path.join(config.staticRoot, pathname);
168	  const resolvedPath = path.resolve(requested);
169	
170	  if (resolvedPath !== rootDir && !resolvedPath.startsWith(rootDir + path.sep)) {
171	    return sendText(res, 403, 'Forbidden');
172	  }
173	
174	  let content;
175	  try {
176	    content = await fs.readFile(resolvedPath);
177	  } catch {
178	    return sendText(res, 404, 'Not Found');
179	  }
180	
181	  const contentType = MIME_TYPES[path.extname(resolvedPath).toLowerCase()] ?? 'application/octet-stream';
182	  res.writeHead(200, { 'Content-Type': contentType });
183	  res.end(content);
184	}
185	
186	function sendJson(res, statusCode, payload) {
187	  res.writeHead(statusCode, { 'Content-Type': 'application/json; charset=utf-8' });
188	  res.end(JSON.stringify(payload));
189	}
190	
191	function sendText(res, statusCode, message) {
192	  res.writeHead(statusCode, { 'Content-Type': 'text/plain; charset=utf-8' });
193	  res.end(message);
194	}
195	
196	function startServer(httpServer, config, startOptions) {
197	  const envPort = Number.parseInt(process.env[config.portEnv] ?? '', 10);
198	  const port = startOptions.port ?? (Number.isNaN(envPort) ? undefined : envPort) ?? config.defaultPort;
199	
200	  return new Promise((resolve, reject) => {
201	    const onError = (error) => {
202	      httpServer.off('error', onError);
203	      reject(error);
204	    };
205	    httpServer.once('error', onError);
206	
207	    httpServer.listen(port, '127.0.0.1', () => {
208	      httpServer.off('error', onError);
209	      const actualPort = httpServer.address().port;
210	      resolve({
211	        origin: `http://127.0.0.1:${actualPort}`,
212	        port: actualPort,
213	        stop: () => stopServer(httpServer),
214	      });
215	    });
216	  });
217	}
218	
219	function stopServer(httpServer) {
220	  return new Promise((resolve, reject) => {
221	    httpServer.close((error) => {
222	      if (error && error.code !== 'ERR_SERVER_NOT_RUNNING') {
223	        reject(error);
224	        return;
225	      }
226	      resolve();
227	    });
228	    httpServer.closeAllConnections();
229	  });
230	}
231	
232	module.exports = { createServer };

