const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const path = require('node:path');

const { createServer } = require('../../server/server.js');

const REPO_ROOT = path.join(__dirname, '..', '..');
const INDEX_HTML_PATH = path.join(REPO_ROOT, 'web', 'index.html');
const LEVEL_SELECT_JS_PATH = path.join(REPO_ROOT, 'web', 'level-select.js');

const DIFFICULTIES = ['简单', '普通', '困难'];

async function startDefaultServer(t) {
  const started = await createServer().start({ port: 0 });

  assert.equal(typeof started.stop, 'function', 'start({ port: 0 }) 应返回 stop 函数');
  assert.ok(Number.isInteger(started.port) && started.port > 0, 'port 应为实际监听端口');
  assert.equal(
    started.origin,
    `http://127.0.0.1:${started.port}`,
    'origin 应为 http://127.0.0.1:<实际端口>'
  );

  t.after(async () => {
    await started.stop();
  });
  return started;
}

test('AC-009 默认配置服务 GET / 返回 web/index.html 且同源 GET /api/levels 返回 200 与逐项满足 CT-002 的 5 项数组', async (t) => {
  const { origin } = await startDefaultServer(t);

  const pageRes = await fetch(`${origin}/`);
  assert.equal(pageRes.status, 200, 'GET / 应返回 200');
  assert.equal(pageRes.headers.get('content-type'), 'text/html; charset=utf-8');

  const html = await pageRes.text();
  const htmlOnDisk = await fs.readFile(INDEX_HTML_PATH, 'utf8');
  assert.equal(html, htmlOnDisk, 'GET / 应原样返回 web/index.html 关卡选择页');

  const apiRes = await fetch(`${origin}/api/levels`);
  assert.equal(apiRes.status, 200, '同源 GET /api/levels 应返回 200');
  assert.equal(apiRes.headers.get('content-type'), 'application/json; charset=utf-8');

  const levels = await apiRes.json();
  assert.ok(Array.isArray(levels), '响应体应为顶层数组');
  assert.equal(levels.length, 5, '关卡数量应恰好为 5');

  const ids = new Set();
  levels.forEach((level, index) => {
    const label = `第 ${index + 1} 项`;
    assert.equal(typeof level, 'object', `${label} 应为对象`);
    assert.ok(level !== null, `${label} 应为非 null 对象`);
    assert.equal(typeof level.id, 'string', `${label} id 应为字符串`);
    assert.ok(level.id.length > 0, `${label} id 应非空`);
    assert.equal(typeof level.name, 'string', `${label} name 应为字符串`);
    assert.ok(level.name.length > 0, `${label} name 应非空`);
    assert.ok(DIFFICULTIES.includes(level.difficulty), `${label} difficulty 非法：${level.difficulty}`);
    assert.equal(typeof level.unlocked, 'boolean', `${label} unlocked 应为布尔值`);
    ids.add(level.id);
  });
  assert.equal(ids.size, 5, '关卡 id 应在文件内唯一');
});

test('AC-010 GET / 的 HTML 含 loading/level-list/error-message 容器与脚本引用且脚本以相对路径引用 /api/levels', async (t) => {
  const { origin } = await startDefaultServer(t);

  const html = await (await fetch(`${origin}/`)).text();
  for (const id of ['loading', 'level-list', 'error-message']) {
    assert.ok(html.includes(`id="${id}"`), `HTML 应包含 id=${id} 容器标记`);
  }
  assert.match(
    html,
    /<script[^>]*\ssrc=["']level-select\.js["'][^>]*>/,
    'HTML 应通过 script 标签引用 level-select.js'
  );

  const scriptRes = await fetch(`${origin}/level-select.js`);
  assert.equal(scriptRes.status, 200, 'GET /level-select.js 应返回 200');
  assert.equal(scriptRes.headers.get('content-type'), 'text/javascript; charset=utf-8');

  const script = await scriptRes.text();
  const scriptOnDisk = await fs.readFile(LEVEL_SELECT_JS_PATH, 'utf8');
  assert.equal(script, scriptOnDisk, 'GET /level-select.js 应原样返回 web/level-select.js 内容');

  assert.ok(script.includes("'/api/levels'"), '脚本应以相对路径 /api/levels 引用关卡 API');
  assert.ok(!/https?:\/\//.test(script), '脚本不应以绝对 URL 引用关卡 API');
});

test('AC-011 未知 API 路径返回 404、POST /api/levels 返回 405 且错误体为 error.code/error.message JSON 结构', async (t) => {
  const { origin } = await startDefaultServer(t);

  const notFoundRes = await fetch(`${origin}/api/unknown`);
  assert.equal(notFoundRes.status, 404, '未知 API 路径应返回 404');
  assert.equal(notFoundRes.headers.get('content-type'), 'application/json; charset=utf-8');

  const notFoundBody = await notFoundRes.json();
  assert.equal(typeof notFoundBody.error, 'object', '404 响应应含 error 对象');
  assert.equal(typeof notFoundBody.error.code, 'string', '404 错误体应含 error.code');
  assert.ok(notFoundBody.error.code.length > 0, 'error.code 应非空');
  assert.equal(typeof notFoundBody.error.message, 'string', '404 错误体应含 error.message');
  assert.ok(notFoundBody.error.message.length > 0, 'error.message 应非空');

  const methodRes = await fetch(`${origin}/api/levels`, { method: 'POST' });
  assert.equal(methodRes.status, 405, 'POST /api/levels 应返回 405');
  assert.equal(methodRes.headers.get('content-type'), 'application/json; charset=utf-8');

  const methodBody = await methodRes.json();
  assert.equal(typeof methodBody.error, 'object', '405 响应应含 error 对象');
  assert.equal(typeof methodBody.error.code, 'string', '405 错误体应含 error.code');
  assert.ok(methodBody.error.code.length > 0, 'error.code 应非空');
  assert.equal(typeof methodBody.error.message, 'string', '405 错误体应含 error.message');
  assert.ok(methodBody.error.message.length > 0, 'error.message 应非空');
});
