{"content":"'use strict';

(function (global) {
  const LEVELS_API_PATH = '/api/levels';
  const DIFFICULTIES = ['简单', '普通', '困难'];

  const MESSAGES = {
    network: '无法连接服务器，请检查网络后重试',
    invalidData: '关卡数据格式不正确，请稍后重试',
    http(status) {
      return `加载关卡失败（HTTP ${status}），请稍后重试`;
    },
  };

  async function initLevelSelect(options) {
    const config = options || {};
    const doc = config.document || global.document;
    const fetchImpl =
      typeof config.fetchImpl === 'function'
        ? config.fetchImpl
        : typeof global.fetch === 'function'
          ? global.fetch.bind(global)
          : null;

    if (!doc || typeof doc.getElementById !== 'function' || !fetchImpl) {
      throw new TypeError('initLevelSelect 需要提供 document 与 fetchImpl（或全局 fetch）');
    }

    const loading = doc.getElementById('loading');
    const list = doc.getElementById('level-list');
    const errorBox = doc.getElementById('error-message');
    if (!loading || !list || !errorBox) {
      throw new Error('页面缺少 #loading、#level-list 或 #error-message 容器');
    }

    enterLoadingState(loading, errorBox);

    let levels;
    try {
      const response = await fetchImpl(LEVELS_API_PATH);
      levels = await readLevels(response);
    } catch (error) {
      const message =
        error && typeof error.friendlyMessage === 'string' ? error.friendlyMessage : MESSAGES.network;
      showErrorState(loading, errorBox, message);
      return;
    }

    renderLevels(doc, list, levels);
    showSuccessState(loading, errorBox);
  }

  async function readLevels(response) {
    if (!isSuccessfulResponse(response)) {
      const status = response && response.status !== undefined ? response.status : '未知状态';
      const detail = await readErrorMessage(response);
      throw friendlyError(detail ? `${MESSAGES.http(status)}：${detail}` : MESSAGES.http(status));
    }

    let data;
    try {
      data = await response.json();
    } catch {
      throw friendlyError(MESSAGES.invalidData);
    }

    return validateLevels(data);
  }

  function isSuccessfulResponse(response) {
    if (!response) {
      return false;
    }
    if (typeof response.ok === 'boolean') {
      return response.ok;
    }
    const status = Number(response.status);
    return status >= 200 && status < 300;
  }

  async function readErrorMessage(response) {
    try {
      const payload = await response.json();
      const message = payload && payload.error && payload.error.message;
      return typeof message === 'string' && message.length > 0 ? message : null;
    } catch {
      return null;
    }
  }

  function validateLevels(data) {
    if (!Array.isArray(data)) {
      throw friendlyError(MESSAGES.invalidData);
    }

    const seenIds = new Set();
    for (const level of data) {
      if (typeof level !== 'object' || level === null || Array.isArray(level)) {
        throw friendlyError(MESSAGES.invalidData);
      }
      if (typeof level.id !== 'string' || level.id.length === 0 || seenIds.has(level.id)) {
        throw friendlyError(MESSAGES.invalidData);
      }
      seenIds.add(level.id);
      if (typeof level.name !== 'string' || level.name.length === 0) {
        throw friendlyError(MESSAGES.invalidData);
      }
      if (!DIFFICULTIES.includes(level.difficulty)) {
        throw friendlyError(MESSAGES.invalidData);
      }
      if (typeof level.unlocked !== 'boolean') {
        throw friendlyError(MESSAGES.invalidData);
      }
    }

    return data;
  }

  function renderLevels(doc, list, levels) {
    list.textContent = '';

    for (const level of levels) {
      const item = doc.createElement('li');
      item.className = level.unlocked ? 'level-item' : 'level-item level-item--locked';
      item.setAttribute('data-level-id', level.id);

      if (level.unlocked) {
        item.addEventListener('click', () => toggleSelected(item));
      } else {
        item.setAttribute('aria-disabled', 'true');
      }

      const name = doc.createElement('span');
      name.className = 'level-item__name';
      name.textContent = level.name;

      const difficulty = doc.createElement('span');
      difficulty.className = 'level-item__difficulty';
      difficulty.textContent = level.difficulty;

      item.appendChild(name);
      item.appendChild(difficulty);
      list.appendChild(item);
    }
  }

  function toggleSelected(item) {
    if (item.getAttribute('data-selected') === 'true') {
      item.removeAttribute('data-selected');
    } else {
      item.setAttribute('data-selected', 'true');
    }
  }

  function enterLoadingState(loading, errorBox) {
    loading.removeAttribute('hidden');
    errorBox.setAttribute('hidden', '');
    errorBox.textContent = '';
  }

  function showSuccessState(loading, errorBox) {
    loading.setAttribute('hidden', '');
    errorBox.setAttribute('hidden', '');
    errorBox.textContent = '';
  }

  function showErrorState(loading, errorBox, message) {
    loading.setAttribute('hidden', '');
    errorBox.textContent = message;
    errorBox.removeAttribute('hidden');
  }

  function friendlyError(message) {
    const error = new Error(message);
    error.friendlyMessage = message;
    return error;
  }

  const api = { initLevelSelect };

  if (typeof module === 'object' && module !== null && typeof module.exports === 'object') {
    module.exports = api;
  }
  global.initLevelSelect = initLevelSelect;
})(typeof window !== 'undefined' ? window : globalThis);
