30	  };
31	  element.setAttribute = (name, value) => {
32	    element.attributes[name] = String(value);
33	  };
34	  element.getAttribute = (name) =>
35	    Object.prototype.hasOwnProperty.call(element.attributes, name) ? element.attributes[name] : null;
36	  element.hasAttribute = (name) => Object.prototype.hasOwnProperty.call(element.attributes, name);
37	  element.removeAttribute = (name) => {
