const test = require('node:test');
const assert = require('node:assert/strict');

const { createServer } = require('../../server/server.js');

test('AC-005 start({ port: 0 }) resolve { origin, port, stop } 且 stop() 完成后关闭连接', async () => {
  const started = await createServer().start({ port: 0 });

  assert.equal(typeof started.stop, 'function', '应返回 stop 函数');
  assert.ok(Number.isInteger(started.port), 'port 应为整数');
  assert.ok(started.port > 0, 'port 应为实际监听端口');
  assert.equal(started.origin, `http://127.0.0.1:${started.port}`, 'origin 应为 http://127.0.0.1:<实际端口>');

  const serving = await fetch(`${started.origin}/api/levels`);
  assert.equal(serving.status, 200, '停止前服务应可用');

  await started.stop();

