29	    const loading = doc.getElementById('loading');
30	    const list = doc.getElementById('level-list');
31	    const errorBox = doc.getElementById('error-message');
32	    if (!loading || !list || !errorBox) {
33	      throw new Error('页面缺少 #loading、#level-list 或 #error-message 容器');
34	    }
35	
36	    enterLoadingState(loading, errorBox);
37	
38	    let levels;
39	    try {
40	      const response = await fetchImpl(LEVELS_API_PATH);
41	      levels = await readLevels(response);
42	    } catch (error) {
43	      const message =
44	        error && typeof error.friendlyMessage === 'string' ? error.friendlyMessage : MESSAGES.network;
45	      showErrorState(loading, errorBox, message);
46	      return;
47	    }
48	
49	    renderLevels(doc, list, levels);
50	    showSuccessState(loading, errorBox);
51	  }
52	
53	  async function readLevels(response) {
54	    if (!isSuccessfulResponse(response)) {
55	      const status = response && response.status !== undefined ? response.status : '未知状态';
56	      const detail = await readErrorMessage(response);
57	      throw friendlyError(detail ? `${MESSAGES.http(status)}：${detail}` : MESSAGES.http(status));
58	    }
59	
60	    let data;
61	    try {
62	      data = await response.json();
63	    } catch {
64	      throw friendlyError(MESSAGES.invalidData);
65	    }
66	
67	    return validateLevels(data);
68	  }
69	
70	  function isSuccessfulResponse(response) {
71	    if (!response) {
72	      return false;
73	    }
74	    if (typeof response.ok === 'boolean') {
75	      return response.ok;
76	    }
77	    const status = Number(response.status);
78	    return status >= 200 && status < 300;
79	  }
80	
81	  async function readErrorMessage(response) {
82	    try {
83	      const payload = await response.json();
84	      const message = payload && payload.error && payload.error.message;
85	      return typeof message === 'string' && message.length > 0 ? message : null;
86	    } catch {
87	      return null;
88	    }
89	  }
90	
91	  function validateLevels(data) {
92	    if (!Array.isArray(data)) {
93	      throw friendlyError(MESSAGES.invalidData);
94	    }
95	
96	    const seenIds = new Set();
97	    for (const level of data) {
98	      if (typeof level !== 'object' || level === null || Array.isArray(level)) {
99	        throw friendlyError(MESSAGES.invalidData);
100	      }
101	      if (typeof level.id !== 'string' || level.id.length === 0 || seenIds.has(level.id)) {
102	        throw friendlyError(MESSAGES.invalidData);
103	      }
104	      seenIds.add(level.id);
105	      if (typeof level.name !== 'string' || level.name.length === 0) {
106	        throw friendlyError(MESSAGES.invalidData);
107	      }
108	      if (!DIFFICULTIES.includes(level.difficulty)) {
109	        throw friendlyError(MESSAGES.invalidData);
110	      }
111	      if (typeof level.unlocked !== 'boolean') {
112	        throw friendlyError(MESSAGES.invalidData);
113	      }
114	    }
115	
116	    return data;
117	  }
118	
119	  function renderLevels(doc, list, levels) {
120	    list.textContent = '';
121	
122	    for (const level of levels) {
123	      const item = doc.createElement('li');
124	      item.className = level.unlocked ? 'level-item' : 'level-item level-item--locked';
125	      item.setAttribute('data-level-id', level.id);
126	
127	      if (level.unlocked) {
128	        item.addEventListener('click', () => toggleSelected(item));
129	      } else {
130	        item.setAttribute('aria-disabled', 'true');
131	      }
132	
133	      const name = doc.createElement('span');
134	      name.className = 'level-item__name';
135	      name.textContent = level.name;
136	
137	      const difficulty = doc.createElement('span');
138	      difficulty.className = 'level-item__difficulty';
139	      difficulty.textContent = level.difficulty;
140	
141	      item.appendChild(name);
142	      item.appendChild(difficulty);
143	      list.appendChild(item);
144	    }
145	  }
146	
147	  function toggleSelected(item) {
148	    if (item.getAttribute('data-selected') === 'true') {
149	      item.removeAttribute('data-selected');
150	    } else {
151	      item.setAttribute('data-selected', 'true');
152	    }
153	  }
154	
155	  function enterLoadingState(loading, errorBox) {
156	    loading.removeAttribute('hidden');
157	    errorBox.setAttribute('hidden', '');
158	    errorBox.textContent = '';
159	  }
160	
161	  function showSuccessState(loading, errorBox) {
162	    loading.setAttribute('hidden', '');
163	    errorBox.setAttribute('hidden', '');
164	    errorBox.textContent = '';
165	  }
166	
167	  function showErrorState(loading, errorBox, message) {
168	    loading.setAttribute('hidden', '');
169	    errorBox.textContent = message;
170	    errorBox.removeAttribute('hidden');
171	  }
