3	(function (global) {
4	  const LEVELS_API_PATH = '/api/levels';
5	  const DIFFICULTIES = ['简单', '普通', '困难'];
6	
7	  const MESSAGES = {
8	    network: '无法连接服务器，请检查网络后重试',
9	    invalidData: '关卡数据格式不正确，请稍后重试',
10	    http(status) {
11	      return `加载关卡失败（HTTP ${status}），请稍后重试`;
