15	  async function initLevelSelect(options) {
16	    const config = options || {};
17	    const doc = config.document || global.document;
18	    const fetchImpl =
19	      typeof config.fetchImpl === 'function'
20	        ? config.fetchImpl
21	        : typeof global.fetch === 'function'
22	          ? global.fetch.bind(global)
23	          : null;
24	
25	    if (!doc || typeof doc.getElementById !== 'function' || !fetchImpl) {
26	      throw new TypeError('initLevelSelect 需要提供 document 与 fetchImpl（或全局 fetch）');
27	    }
